import (
 "fmt"
 "strings"

 "github.com/mattn/anko/ast"
)

type defaultToken struct { kind, start, end int; lit string; pos ast.Position }

// lowerDefaults translates optional parameters into a variadic parameter and
// local bindings. The regular parser still parses all default expressions.
func lowerDefaults(src []rune) ([]rune, error) {
 for {
  scanner := &Scanner{src: src}
  var tokens []defaultToken
  lines := []int{0}
  for i, r := range src { if r == '\n' { lines = append(lines, i+1) } }
  for {
   k, lit, pos, err := scanner.Scan()
   if err != nil || k == EOF { break }
   start := lines[pos.Line-1]+pos.Column-1
   tokens = append(tokens, defaultToken{k,start,scanner.offset,lit,pos})
  }
  changed := false
  for i := len(tokens)-1; i >= 0; i-- {
   if tokens[i].kind != FUNC { continue }
   j := i+1
   if j < len(tokens) && tokens[j].kind == IDENT { j++ }
   if j >= len(tokens) || tokens[j].kind != '(' { continue }
   open := j
   depth := 0
   var parts [][2]int
   start := j+1
   close := -1
   for j++; j < len(tokens); j++ {
    switch tokens[j].kind {
    case '(', '[', '{': depth++
    case ')':
     if depth == 0 { parts = append(parts,[2]int{start,j}); close=j } else { depth-- }
    case ']', '}': depth--
    case ',': if depth == 0 { parts=append(parts,[2]int{start,j}); start=j+1 }
    }
    if close >= 0 { break }
   }
   if close < 0 || close+1 >= len(tokens) || tokens[close+1].kind != '{' { continue }
   type param struct { name, value string; variadic bool }
   var params []param
   seen, any := false, false
   invalid := false
   for _, part := range parts {
    a,b := part[0],part[1]
    for a < b && tokens[a].kind == '\n' { a++ }
    for b > a && tokens[b-1].kind == '\n' { b-- }
    if a == b { continue }
    if tokens[a].kind != IDENT { invalid=true; break }
    p := param{name:tokens[a].lit}; a++
    if a < b && tokens[a].kind == VARARG { p.variadic=true; a++ }
    if a < b && tokens[a].kind == '=' {
     any=true; seen=true
     if p.variadic || a+1 >= b { invalid=true; break }
     p.value=string(src[tokens[a].end:tokens[b-1].end])
     if tokens[b-1].kind == VARARG { invalid=true; break }
     a=b
    } else if seen && !p.variadic { invalid=true; break }
    if a != b { invalid=true; break }
    params=append(params,p)
   }
   if invalid {
    if seen || any { return nil, &Error{Message:"invalid default argument declaration",Pos:tokens[i].pos} }
    continue
   }
   if !any { continue }
   required:=0
   for required<len(params) && params[required].value=="" && !params[required].variadic { required++ }
   name:="__anko_default_args"
   for strings.Contains(string(src), name) { name += "_" }
   header:=make([]string,0,required+1)
   for _, p := range params[:required] { header=append(header,p.name) }
   header=append(header,name+"...")
   var body strings.Builder
   optional:=0
   for _, p := range params[required:] {
    if p.variadic {
     fmt.Fprintf(&body,"var %s = len(%s) > %d ? %s[%d:] : [];",p.name,name,optional,name,optional)
    } else {
     fmt.Fprintf(&body,"var %s = len(%s) > %d ? %s[%d] : (%s);",p.name,name,optional,name,optional,p.value)
     optional++
    }
   }
   if len(params)>0 && !params[len(params)-1].variadic { fmt.Fprintf(&body,"if len(%s) > %d { throw \"too many arguments\" };",name,optional) }
   replacement:=[]rune(strings.Join(header,", "))
   // Preserve line count in the header for subsequent diagnostics.
   for _, r := range src[tokens[open].end:tokens[close].start] { if r=='\n' { replacement=append(replacement,'\n') } }
   next:=make([]rune,0,len(src)+body.Len())
   next=append(next,src[:tokens[open].end]...); next=append(next,replacement...)
   next=append(next,src[tokens[close].start:tokens[close+1].end]...); next=append(next,[]rune(body.String())...)
   next=append(next,src[tokens[close+1].end:]...)
   src=next; changed=true; break
  }
  if !changed { return src,nil }
 }
}
"}

